// Parse and validate input
const input = $input.first().json;
const body = input.body || input;

if (!body.translation) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_TRANSLATION', message: 'translation is required' }
    }
  }];
}

if (!body.commentary_id && !body.source_text_id) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_ID', message: 'Either commentary_id or source_text_id is required' }
    }
  }];
}

return [{
  json: {
    jobId: body.job_id,
    translation: body.translation,
    commentaryId: body.commentary_id || null,
    sourceTextId: body.source_text_id || null,
    targetLanguage: body.target_language || 'fr',
    provider: body.provider || 'anthropic',
    model: body.model || 'claude-sonnet-4-20250514',
    tokens: body.tokens || null,
    metadata: body.metadata || {}
  }
}];

// Format response
const input = $input.first().json;

if (input.error) {
  return [{
    json: {
      success: false,
      error: {
        code: 'SAVE_ERROR',
        message: input.error.message || 'Failed to save translation'
      }
    }
  }];
}

return [{
  json: {
    success: input.success !== false,
    saved_id: input.translation_id || input.commentary_id || input.source_text_id,
    message: input.message || 'Translation saved'
  }
}];
